 5  char *remove_parenthesis(const char *str, size_t len) {
 6      if (str == NULL || len == 0) {
 7          return NULL;
 8      }
 9  
10      char *result = (char *)malloc(len + 1);
11      if (result == NULL) {
12          return NULL;
13      }
14  
15      size_t j = 0;
16      int depth = 0;
17  
18      for (size_t i = 0; i < len; i++) {
19          if (str[i] == '(') {
20              depth++;
21          } else if (str[i] == ')') {
22              if (depth > 0) {
23                  depth--;
24              } else {
25                  result[j++] = str[i];
26              }
27          } else {
28              if (depth == 0) {
29                  result[j++] = str[i];
30              }
31          }
32      }
33  
34      result[j] = '\0';
35  
36      char *shrunk = (char *)realloc(result, j + 1);
37      if (shrunk != NULL) {
38          result = shrunk;
39      }
40  
41      return result;
42  }
43  
