15          result.size = 0;
16          return result;
17      }
18      
19      if (tuple->size > SIZE_MAX / n || (tuple->size * n) > SIZE_MAX / sizeof(int)) {
20          result.elements = NULL;
21          result.size = 0;
22          return result;
23      }
24      
25      result.size = tuple->size * n;
26      result.elements = (int *)malloc(result.size * sizeof(int));
27      
28      if (result.elements == NULL) {
29          result.size = 0;
30          return result;
31      }
32      
33      for (size_t i = 0; i < n; i++) {
34          size_t offset = i * tuple->size;
35          if (offset + tuple->size > result.size) {
36              break;
37          }
38          memcpy(result.elements + offset, 
39                 tuple->elements, 
40                 tuple->size * sizeof(int));
41      }
42      
43      return result;
44  }
45  
46  void free_tuple(Tuple *tuple) {
47      if (tuple != NULL) {
48          free(tuple->elements);
49          tuple->elements = NULL;
50          tuple->size = 0;
51      }
52  }
53  
54  int main(void) {
55      int arr[] = {1, 2, 3};
56      int *heap_arr = (int *)malloc(3 * sizeof(int));
57      if (heap_arr == NULL) {
58          fprintf(stderr, "Memory allocation failed\n");
59          return 1;
60      }
61      memcpy(heap_arr, arr, 3 * sizeof(int));
62      
63      Tuple original;
64      original.elements = heap_arr;
65      original.size = 3;
66      
67      size_t n = 4;
68      Tuple repeated = repeat_tuple(&original, n);
69      
70      if (repeated.elements == NULL) {
71          fprintf(stderr, "Memory allocation failed\n");
72          free_tuple(&original);
73          return 1;
74      }
75      
76      printf("Repeated tuple: ");
77      for (size_t i = 0; i < repeated.size; i++) {
78          printf("%d ", repeated.elements[i]);
79      }
80      printf("\n");
81      
82      free_tuple(&repeated);
83      free_tuple(&original);
84      
85      return 0;
86  }

